#include <iostream>
#include <mutex>
#include <chrono>

class TimerMutex {
public:
    template <class Clock, class Duration>
    bool try_lock_for(const std::chrono::duration<Clock, Duration>& rel_time) {
        // Simulate a timed lock attempt
        std::cout << "Trying to lock for " << rel_time.count() << " units." << std::endl;
        // For demonstration, assume lock is always acquired
        return true;
    }
};

int main() {
    TimerMutex mtx;
    // Using different duration types
    mtx.try_lock_for(std::chrono::seconds(2));
    mtx.try_lock_for(std::chrono::milliseconds(500));
    mtx.try_lock_for(std::chrono::nanoseconds(100000));
    return 0;
}
